/**
 * emit to subscription queries of type FindAdAccount,
 * but only if the id matches
 *
 * @param		entity	AdAccount
 */
	protected void emitFindAdAccount( AdAccount entity ) {
		LOGGER.info("handling emitFindAdAccount" );
		
	    queryUpdateEmitter.emit(FindAdAccountQuery.class,
	                            query -> query.getFilter().getAdAccountId().equals(entity.getAdAccountId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAdAccount
	 * 
	 * @param		entity	AdAccount
	 */
	protected void emitFindAllAdAccount( AdAccount entity ) {
		LOGGER.info("handling emitFindAllAdAccount" );
		
	    queryUpdateEmitter.emit(FindAllAdAccountQuery.class,
	                            query -> true,
	                            entity);
	}

